from taf.ul.ettf.sim.simulators.simulators_map import AVAILABLE_SIMULATORS
from taf.ul.ettf.utils.provider import chosen_simulator
from taf.ul.ettf.sim.core.library import error_message, name, LibraryError
from taf.ul.ettf.logger import custom_logger


logger = custom_logger('simulator_library')


class WrongSimulatorChosen(LibraryError):
    def __init__(self, msg):
        super(WrongSimulatorChosen, self).__init__('EXPECTED SIMULATOR DOES NOT EXIST', msg)


class simulator_provider(object):
    ROBOT_LIBRARY_SCOPE = 'SUITE'
    default_simulator = 'Egate'

    def get_simulator(self):
        command_line_simulator = chosen_simulator()

        if command_line_simulator:
            if command_line_simulator in AVAILABLE_SIMULATORS.keys():
                logger.warn('{}: Simulator chosen from commandline: {}'.format(name(self), AVAILABLE_SIMULATORS[command_line_simulator]()))
                return AVAILABLE_SIMULATORS[command_line_simulator]()
            else:
                logger.error(error_message(self, self.default_simulator))
                raise WrongSimulatorChosen(error_message(self, self.default_simulator))
        elif self.default_simulator in AVAILABLE_SIMULATORS.keys():
            return AVAILABLE_SIMULATORS[self.default_simulator]()
        else:
            logger.error(error_message(self, self.default_simulator))
            raise WrongSimulatorChosen(error_message(self, self.default_simulator))

    @property
    def simulator(self):
        return self.get_simulator()
